"""Rechallenge 32 report survivors by executing real original and mutated source copies.
Run from the repository root. Optional: --baseline PATH --output PATH.
Only focused fixtures run; no mutation campaign, status rewrite, or exclusion is performed.
"""
import argparse, ast, base64, codecs, contextlib, copy, hashlib, importlib.util, io, json, os, pathlib, shutil, subprocess, sys, tempfile
from types import SimpleNamespace
from unittest.mock import patch


def frozen(value):
    if isinstance(value, pathlib.Path): return str(value)
    if isinstance(value, dict): return {str(key):frozen(item) for key,item in value.items()}
    if isinstance(value,(list,tuple)): return [frozen(item) for item in value]
    return value


def observe(function,*args,**kwargs):
    try: return {'returned':frozen(function(*args,**kwargs))}
    except Exception as error: return {'exception':type(error).__name__,'message':str(error)}


def worker(module_path, repository, fixture, function_name, regime):
    scripts=repository/'skills/workflow/scripts'
    sys.path.insert(0,str(scripts))
    spec=importlib.util.spec_from_file_location('audit_target',module_path)
    module=importlib.util.module_from_spec(spec);spec.loader.exec_module(module)
    fixture.mkdir(parents=True,exist_ok=True);os.chdir(fixture)
    observations=[]
    raw=[]
    write_text=pathlib.Path.write_text
    def utf7_write(path,text,*args,encoding=None,**kwargs):
        return write_text(path,text,*args,encoding=encoding or 'utf-7',**kwargs)
    locale_context=patch.object(pathlib.Path,'write_text',utf7_write) if regime=='utf7' else contextlib.nullcontext()
    with locale_context:
        target=getattr(module,function_name)
        if function_name=='read_lcov':
            source=(fixture/'源+😀.py').resolve()
            report=fixture/'report.lcov'
            for content in (f'SF:{source}\nDA:1,1\nend_of_record\n'.encode('utf-8'),b'SF:\xff\n'):
                report.write_bytes(content);observations.append(observe(target,report))
        elif function_name=='validate_checksums':
            # Every possible final digest byte: exhaustive relevant Base64 suffix space.
            suffixes=set()
            for byte in range(256):
                encoded=base64.b64encode(b'\0'*15+bytes([byte])).decode('ascii')
                suffixes.add(encoded.rstrip('=')[-1]);assert encoded.rstrip('=')==encoded.rstrip('XX=XX')
            assert suffixes==set('AQgw')
            for text in ('','ascii+','你好😀','\ud800'):
                try: checksum=base64.b64encode(hashlib.md5(text.encode('utf-8'),usedforsecurity=False).digest()).decode('ascii').rstrip('=')
                except UnicodeEncodeError: checksum='invalid'
                observations.append(observe(target,'源.py',[text],{1:checksum}))
                observations.append(observe(target,'源.py',[text],{1:'wrong'}))
            # Both implementations use a truth-value conversion for this flag.
            import _md5
            for constructor in (hashlib.md5,_md5.md5):
                for data in (b'',b'abc','你好'.encode('utf-8')):
                    assert constructor(data,usedforsecurity=False).digest()==constructor(data,usedforsecurity=None).digest()
        elif function_name=='coverage_commands':
            project=fixture/'项目+plus'
            observations.append(observe(target,project,fixture,['-m','unittest']))
            raw.append((fixture/'coveragerc').read_text(encoding='utf-8'))
        elif function_name=='collect':
            folder=fixture/'mutants/包+😀';folder.mkdir(parents=True)
            path=folder/'source.meta'
            path.write_text(json.dumps({'exit_code_by_key':{'模块.x_函数__mutmut_1':0,'模块.x_函数__mutmut_2':1}},ensure_ascii=False),encoding='utf-8')
            observations.append(observe(target,fixture/'mutants',{}))
            path.write_bytes(b'\xff');observations.append(observe(target,fixture/'mutants',{}))
        elif function_name=='function_position':
            source=fixture/'源+😀.py'
            source.write_text('def 前置():\n    pass\n\n@staticmethod\ndef 目标():\n    return "你好"\n\nclass Box:\n    @staticmethod\n    async def 目标():\n        return "😀"\n',encoding='utf-8')
            for name,klass in (('目标',None),('目标','Box'),('absent',None)):
                observations.append(observe(target,source,name,klass))
            source.write_bytes(b'\xff');observations.append(observe(target,source,'目标',None))
        elif function_name=='add_details':
            from mutmut.configuration import _load_config
            from mutmut.mutation.data import MutantLineSpans,SourceFileMutationData
            from mutmut.mutation.file_mutation import mutate_file_contents
            from mutmut.mutation.diff_apply import get_diff_for_mutant
            (fixture/'pyproject.toml').write_text('[tool.mutmut]\nsource_paths=["src/"]\n',encoding='utf-8')
            code='@staticmethod\ndef choose(a,b):\n    return a+b\n\nclass Box:\n    @staticmethod\n    def choose(a,b):\n        return a+b\n'
            names=(('src/Calc.py','Calc'),('src/pkg/math.py','pkg.math'),('src/pkg.Dotted/工具.py','pkg.Dotted.工具'))
            with patch('mutmut.utils.file_utils.config',return_value=_load_config()):
                cases=[]
                for relative,prefix in names:
                    path=pathlib.Path(relative);path.parent.mkdir(parents=True,exist_ok=True);path.write_text(code,encoding='utf-8')
                    generated=mutate_file_contents(str(path),code)
                    mutated=pathlib.Path('mutants')/path;mutated.parent.mkdir(parents=True,exist_ok=True);mutated.write_text(generated.code,encoding='utf-8')
                    MutantLineSpans(path=path,span_by_function_name=generated.line_span_by_function_name).save()
                    data=SourceFileMutationData(path=path)
                    keys=[prefix+'.'+key for key in generated.mutant_names]
                    data.exit_code_by_key={key:0 for key in keys};data.save()
                    selected=[key for key in keys if 'return a-b' in get_diff_for_mutant(key,path=path) or 'return a - b' in get_diff_for_mutant(key,path=path)]
                    assert len(selected)==2,selected
                    cases.extend({'id':key,'status':'survived'} for key in selected)
                # Real file walker, parser and diff extractor; no mocked path lookup.
                observations.append(observe(target,copy.deepcopy(cases)))
                observations.append(observe(target,[{'id':'missing.x_choose__mutmut_1','status':'survived'}]))
                observations.append(observe(target,[{'id':cases[0]['id'],'status':'killed'}]))
        elif module_path.name=='lang_python.py' and function_name=='main':
            items=[{'id':'module.x_choose__mutmut_1','status':'survived','file':'源+😀.py',
                    'function':'choose','line':2,'diff':'--- before\n+++ after\n@@ -1 +1 @@\n-return 1\n+return 2'}]
            with patch.dict(sys.modules,{'mutmut.__main__':SimpleNamespace(status_by_exit_code={})}),patch.object(module.subprocess,'run'),patch.object(module,'collect',return_value=items),patch.object(module,'add_details',side_effect=lambda value:value):
                observations.append(observe(target,[str(fixture/'report.json')]))
            report=fixture/'report.json'
            if report.exists():
                raw.append(report.read_text(encoding='utf-8'));observations.append({'report':observe(json.loads,raw[-1])})
        elif module_path.name=='mutation.py' and function_name=='language_result':
            project=fixture/'项目+plus';project.mkdir()
            evidence=fixture/'evidence';evidence.mkdir()
            report='{"baselinePassed":true,"mutants":[{"id":"m+1","status":"killed"}]}'
            command=[sys.executable,'-c','import os,pathlib;pathlib.Path(os.environ["WORKFLOW_REPORT_FILE"]).write_text('+repr(report)+',encoding="utf-8")']
            with patch.object(module,'evidence_directory',return_value=evidence),tempfile.TemporaryFile('w+',encoding='utf-8') as stream,contextlib.redirect_stderr(stream):
                observations.append(observe(target,'python',[str(project),'--',*command]))
            config=evidence/'config.json'
            if config.exists():raw.append(config.read_text(encoding='utf-8'));observations.append({'config':observe(json.loads,raw[-1])})
        elif module_path.name=='mutation.py' and function_name=='main':
            from shared_runner import read_json
            report={'baselinePassed':True,'mutants':[{'id':'m+😀','status':'survived','file':'源+😀.py','line':1,'extra':1.79e308}]}
            texts=[json.dumps(report),*(json.dumps({'baselinePassed':True,'mutants':[]})[:-1]+',"extra":'+bad+'}' for bad in ('NaN','Infinity','-Infinity','1e999'))]
            for index,text in enumerate(texts):
                output=f'mutation-{index}.json'
                writer='import os,pathlib;pathlib.Path(os.environ["WORKFLOW_REPORT_FILE"]).write_text('+repr(text)+',encoding="utf-8")'
                config=fixture/f'config-{index}.json';config.write_text(json.dumps({'cwd':'.','report':output,'format':'normalized','command':[sys.executable,'-c',writer]}),encoding='utf-8')
                with contextlib.redirect_stdout(io.StringIO()) as stdout,tempfile.TemporaryFile('w+',encoding='utf-8') as stderr,contextlib.redirect_stderr(stderr):
                    call=observe(target,['--json',str(config)])
                    stderr.seek(0);call['stderr']=stderr.read()
                raw.append(stdout.getvalue());call['stdoutParsed']=json.loads(raw[-1]) if raw[-1] else None
                observations.append(call)
        elif function_name=='read_cargo_diff':
            source=fixture/'diff+😀.patch'
            for content in ('---before\n+++after\n-你好\n+😀\n'.encode('utf-8'),b'\xff'):
                source.write_bytes(content);observations.append(observe(target,fixture/'outcomes.json',source.name))
            observations.append(observe(target,fixture/'outcomes.json','../escape'))
        elif function_name=='valid_position':
            for line in ('','a','你好','😀','a😀b\r\n'):
                units=len(line.rstrip('\r\n').encode('utf-16-le'))//2
                for column in range(-1,units+3):observations.append(observe(target,[line],1,column))
            # This is a numerical counterexample, not an impossible fake source object.
            length=2**54;column=2**53+1
            assert (1<=column<=length//2+1) and not (1<=column<=length/2+1)
        elif function_name=='source_offset':
            source='A😀你好\r\nsecond\n'
            for position in ({'line':1,'column':1},{'line':1,'column':2},{'line':1,'column':3},{'line':1,'column':4},{'line':1,'column':6},{'line':3,'column':1},{'line':1,'column':0}):
                observations.append(observe(target,source,position))
            observations.append(observe(target,'\ud800',{'line':1,'column':1}))
        else:raise AssertionError((module_path.name,function_name))
    return {'observations':observations,'rawOutput':raw}


def proof_for(item):
    identifier=item['id'];name=item['function'];diff=item['diff']
    added='\n'.join(line[1:] for line in diff.splitlines() if line.startswith('+') and not line.startswith('+++'))
    removed='\n'.join(line[1:] for line in diff.splitlines() if line.startswith('-') and not line.startswith('---'))
    if any(alias in added for alias in ('"UTF-8"',"'UTF-8'",'"ASCII"','"UTF-16-LE"')):
        return {'classification':'equivalent','kind':'identical-codec','reasoning':'Python codec lookup normalizes case before registry lookup; the changed literal maps to the exact same built-in codec object. Both complete functions perform the same operations on the same bytes/strings, including decoding/encoding failures; there is no path, parsing, gate or report-field change.',
                'boundary':'Python built-in UTF-8/ASCII/UTF-16LE codec registry. No locale assumption is needed because encoding remains explicit.','callers':{'read_lcov':['coverage_lcov.read'], 'validate_checksums':['coverage_lcov.source_coverage'], 'coverage_commands':['lang_python.CRAP.commands via crap.language_result'], 'collect':['lang_python.main'], 'function_position':['lang_python.add_details'], 'main':['lang_python.MUTATION.command via mutation.language_result'], 'language_result':['mutation.dispatch'], 'read_cargo_diff':['report_cargo.cargo_detail'], 'source_offset':['report_stryker.stryker_detail']}[name]}
    if 'usedforsecurity=None' in added:
        return {'classification':'equivalent','kind':'same-false-md5-flag','reasoning':'The standard-library MD5 constructors consume usedforsecurity as a truth value; bool(None)==bool(False)==False. The security policy selection is identical before any data is hashed, so digest computation and FIPS policy behavior are unchanged for every input accepted by the constructors.',
                'boundary':'CPython supported hashlib/OpenSSL or _md5 implementation. A third-party monkeypatch enforcing the exact Python bool type is not a repository dependency.','authoritativeSources':[{'url':'https://docs.python.org/3.14/library/hashlib.html','support':'usedforsecurity selects the non-security path with a false value; available since Python 3.9.'}],'callers':['coverage_lcov.source_coverage']}
    if 'rstrip("XX=XX")' in added:
        return {'classification':'equivalent','kind':'fixed-md5-base64-suffix','reasoning':'MD5 always returns 16 bytes. RFC4648 Base64 therefore has two trailing padding characters and its final payload character encodes only the last two data bits shifted left four places: index 0,16,32,48, hence A,Q,g,w. None is X. rstrip("XX=XX") removes the same two padding characters and stops at the same payload character as rstrip("="); preceding payload characters cannot be reached.',
                'boundary':'A real 16-byte MD5 digest and ordinary base64.b64encode, as both used in the function. Proof depends only on digest length and final two bits, not sampled leading bytes.','callers':['coverage_lcov.source_coverage']}
    if 'encoding=None' in added or ('encoding=' in removed and 'encoding=' not in added):
        return {'classification':'non-equivalent','kind':'lost-explicit-utf8','reasoning':'ensure_ascii makes JSON characters ASCII but does not establish a default-codec or warning-policy contract. Native -X warn_default_encoding -W error::EncodingWarning rejects omitted/None encoding and accepts explicit UTF-8. UTF-7 is also a concrete text-codec counterexample: ASCII + becomes +-, so UTF-8 report consumers see changed source diff fields or a changed project path; the actual mutation config runner then rejects its nonexistent cwd.',
                'boundary':'No repository contract excludes encoding warnings or fixes the process default codec. The UTF-7 exercise is simulated default I/O; the warning counterexample uses native runtime flags with no encoding mock.','callers':['mutation.language_result→run_mutation→read_json' if identifier.startswith('mutation.') else 'lang_python.MUTATION→main→mutation.run_mutation→read_json'],
                'regressionTests':['tests/test_evidence_encoding.py:test_mutation_config_preserves_plus_signs_under_utf7_default','tests/test_evidence_encoding.py:test_python_export_preserves_diff_plus_signs_under_utf7_default','tests/test_evidence_encoding.py:test_evidence_writers_work_with_encoding_warnings_as_errors']}
    if 'indent=2' in removed and ('indent=None' in added or 'indent=3' in added or 'indent=' not in added):
        return {'classification':'equivalent','kind':'parsed-json-only','byteEquivalent':False,'reasoning':'Only the JSON encoder whitespace option changes. JSON grammar allows whitespace between structural tokens; the same encoder escapes and serializes every key/value in the same order. The repository consumers read JSON objects with read_json/json.loads, and the CLI JSON mode declares no fixed indentation or exact-byte contract. Error cases and returned gate code are unchanged. The emitted visible bytes differ; this is semantic consumer equivalence, never byte identity.',
                'boundary':'Actual repository JSON consumers and CLI --json contract. External consumers comparing raw report hashes or depending on pretty indentation are outside the declared interface; sufficient normal I/O resources are assumed.','callers':['mutation.run_mutation→read_json' if identifier.startswith('lang_python.') else 'mutation.run_mutation→read_json' if name=='language_result' else 'CLI --json parsed output']}
    if 'allow_nan=' in removed:
