def main():
    parser=argparse.ArgumentParser();parser.add_argument('--baseline',type=pathlib.Path,default=pathlib.Path(__file__).with_name('baseline-evidence.json'));parser.add_argument('--output',type=pathlib.Path,default=pathlib.Path(__file__).with_name('reports-audit.json'));parser.add_argument('--root',type=pathlib.Path,default=pathlib.Path.cwd());parser.add_argument('--worker',nargs=5)
    args=parser.parse_args()
    if args.worker:
        path,root,fixture,name,regime=args.worker
        print(json.dumps(worker(pathlib.Path(path),pathlib.Path(root),pathlib.Path(fixture),name,regime),ensure_ascii=True));return
    root=args.root.resolve();baseline=json.loads(args.baseline.read_text(encoding='utf-8'))
    selected=[item for item in baseline['equivalents'] if pathlib.Path(item['file']).name in ('coverage_lcov.py','lang_python.py','mutation.py','report_cargo.py','report_stryker.py')];assert len(selected)==32
    audit=[]
    with tempfile.TemporaryDirectory(prefix='workflow-report-survivor-proof-') as directory:
        work=pathlib.Path(directory).resolve()
        for item in selected:
            relative=pathlib.Path('skills/workflow/scripts')/pathlib.Path(item['file']).name
            source=root/relative;text=source.read_text(encoding='utf-8')
            source_hash=hashlib.sha256(source.read_bytes()).hexdigest();assert source_hash==item['sourceSha256'],f'Baseline drift: {relative}'
            node=next(node for node in ast.parse(text).body if isinstance(node,ast.FunctionDef) and node.name==item['function'])
            lines=text.splitlines(keepends=True);body=''.join(lines[node.lineno-1:node.end_lineno])
            old='\n'.join(line[1:] for line in item['diff'].splitlines() if line.startswith('-') and not line.startswith('---'))
            new='\n'.join(line[1:] for line in item['diff'].splitlines() if line.startswith('+') and not line.startswith('+++'))
            assert body.count(old)==1,(item['id'],old)
            changed=''.join(lines[:node.lineno-1])+body.replace(old,new)+''.join(lines[node.end_lineno:])
            case=work/item['id'];case.mkdir()
            originals={}
            for variant,value in (('original',text),('mutant',changed)):
                folder=case/variant;folder.mkdir();path=folder/source.name;path.write_text(value,encoding='utf-8');originals[variant]=path
            regimes=['default']
            claim=proof_for(item)
            if claim['classification']=='non-equivalent':regimes.extend(('strict','utf7'))
            checked=[]
            for regime in regimes:
                pair={}
                fixture=case/'fixture'
                for variant,path in originals.items():
                    if fixture.exists():shutil.rmtree(fixture)
                    flags=['-X','warn_default_encoding','-W','error::EncodingWarning'] if regime=='strict' else []
                    call=subprocess.run([sys.executable,*flags,str(pathlib.Path(__file__).resolve()),'--worker',str(path),str(root),str(fixture),item['function'],regime],capture_output=True,text=True,encoding='utf-8',timeout=60)
                    assert call.returncode==0,(item['id'],regime,variant,call.stderr)
                    pair[variant]=json.loads(call.stdout)
                equal=pair['original']['observations']==pair['mutant']['observations']
                raw_equal=pair['original']['rawOutput']==pair['mutant']['rawOutput']
                checked.append({'regime':regime,'observationEqual':equal,'rawOutputEqual':raw_equal,'original':pair['original'],'mutant':pair['mutant']})
                if claim['classification'] in ('equivalent','equivalent_with_memory_boundary'):assert equal,(item['id'],checked[-1])
            if claim['classification']=='non-equivalent':
                assert any(not check['observationEqual'] for check in checked if check['regime']=='strict')
                assert any(not check['observationEqual'] for check in checked if check['regime']=='utf7')
            audit.append({'original93Id':item['id'],'file':str(relative),'function':item['function'],'sourceSha256':source_hash,
                          'functionSha256':hashlib.sha256(body.encode('utf-8')).hexdigest(),'diff':item['diff'],'diffSha256':hashlib.sha256(item['diff'].encode('utf-8')).hexdigest(),
                          **claim,'executedDifferential':checked})
    payload={'scope':'32 of the original 93 survivors; not a new full mutation measurement','baseline':str(args.baseline),'baselineSha256':hashlib.sha256(args.baseline.read_bytes()).hexdigest(),'python':sys.version,'root':str(root),'notAnExclusionList':True,'automaticallyApproved':False,
             'counts':{'reviewed':len(audit),'equivalent':sum(item['classification']=='equivalent' for item in audit),'equivalentWithMemoryBoundary':sum(item['classification']=='equivalent_with_memory_boundary' for item in audit),'nonEquivalent':sum(item['classification']=='non-equivalent' for item in audit)},'survivors':audit}
    args.output.write_text(json.dumps(payload,ensure_ascii=False,indent=2)+'\n',encoding='utf-8');print(json.dumps(payload['counts']))

if __name__=='__main__':main()

